  'faro.sum.stil': { nl: 'Er kwam niets binnen. Ik hou het in de gaten.', fr: "Rien n'est arrivé. Je garde un œil dessus.", en: "Nothing came in. I'm keeping watch.", de: 'Es kam nichts herein. Ich behalte es im Auge.' },
