  'faro.beoordeling.bron': { nl: 'Bron', fr: 'Source', en: 'Source', de: 'Quelle' },
  'faro.beoordeling.pand': { nl: 'Pand', fr: 'Bien', en: 'Property', de: 'Objekt' },
  'faro.beoordeling.leeg': { nl: 'Hier weet ik nog niets over. Zodra het gesprek loopt, vul ik dit aan.', fr: "Je n'ai encore rien à ce sujet. Dès que la conversation avance, je complète.", en: "I don't know anything about this one yet. Once the conversation gets going, I'll fill this in.", de: 'Dazu weiß ich noch nichts. Sobald das Gespräch läuft, ergänze ich das.' },
  'faro.deed.kop': { nl: 'Wat ik deed', fr: "Ce que j'ai fait", en: 'What I did', de: 'Was ich getan habe' },
  'faro.deed.gesprek': { nl: 'Het gesprek gestart', fr: 'Lancé la conversation', en: 'Started the conversation', de: 'Das Gespräch begonnen' },
  'faro.deed.gekwalificeerd': { nl: 'Deze lead gekwalificeerd', fr: 'Qualifié ce prospect', en: 'Qualified this lead', de: 'Diesen Lead qualifiziert' },
  'faro.deed.boekingslink': { nl: 'Een boekingslink gestuurd', fr: 'Envoyé un lien de réservation', en: 'Sent a booking link', de: 'Einen Buchungslink geschickt' },
  'faro.deed.geboekt': { nl: 'De afspraak geboekt', fr: 'Réservé le rendez-vous', en: 'Booked the appointment', de: 'Den Termin gebucht' },
  'faro.deed.gestopt': { nl: 'Gestopt — hier heb ik jou voor nodig', fr: "Arrêté — j'ai besoin de vous ici", en: 'Stopped — I need you on this one', de: 'Gestoppt — hier brauche ich Sie' },
  'wiz.intro.t': { nl: 'Hallo, ik ben Faro', fr: 'Bonjour, je suis Faro', en: "Hi, I'm Faro", de: 'Hallo, ich bin Faro' },
  'wiz.intro.s': { nl: 'Ik neem je binnenkomende gesprekken over: ik kwalificeer je leads, volg ze op en zet er afspraken uit. Om dat goed te doen heb ik een paar dingen van je nodig.', fr: "Je prends en charge vos conversations entrantes : je qualifie vos prospects, je les relance et j'en tire des rendez-vous. Pour bien le faire, j'ai besoin de quelques informations.", en: "I'll take over your incoming conversations: I qualify your leads, follow up with them, and turn them into appointments. To do that well I need a few things from you.", de: 'Ich übernehme Ihre eingehenden Gespräche: Ich qualifiziere Ihre Leads, hake nach und mache Termine daraus. Dafür brauche ich ein paar Angaben von Ihnen.' },
  'wiz.intro.b1': { nl: 'Waar je werkt en in welke taal ik je klanten aanspreek', fr: "Où vous travaillez et dans quelle langue je m'adresse à vos clients", en: 'Where you work and which language I speak to your customers in', de: 'Wo Sie arbeiten und in welcher Sprache ich Ihre Kunden anspreche' },
  'wiz.intro.b2': { nl: 'Wat je bedrijf doet, zodat ik weet waarover ik praat', fr: 'Ce que fait votre entreprise, pour que je sache de quoi je parle', en: "What your business does, so I know what I'm talking about", de: 'Was Ihr Unternehmen macht, damit ich weiß, worüber ich spreche' },
  'wiz.intro.b3': { nl: 'Onder welke naam ik me voorstel', fr: 'Sous quel nom je me présente', en: 'The name I introduce myself under', de: 'Unter welchem Namen ich mich vorstelle' },
  'wiz.intro.b4': { nl: 'Je WhatsApp en je agenda, zodat ik kan boeken', fr: 'Votre WhatsApp et votre agenda, pour que je puisse réserver', en: 'Your WhatsApp and calendar, so I can book', de: 'Ihr WhatsApp und Ihr Kalender, damit ich buchen kann' },
  'wiz.intro.skip': { nl: 'Je kan dit overslaan en later invullen — je vindt dezelfde stappen terug op je dashboard.', fr: 'Vous pouvez passer et compléter plus tard — vous retrouverez ces étapes sur votre tableau de bord.', en: 'You can skip this and fill it in later — the same steps are on your dashboard.', de: 'Sie können das überspringen und später ausfüllen — dieselben Schritte finden Sie auf Ihrem Dashboard.' },
  'wiz.regio.t': { nl: 'Waar werk je, en in welke taal?', fr: 'Où travaillez-vous, et dans quelle langue ?', en: 'Where do you work, and in which language?', de: 'Wo arbeiten Sie, und in welcher Sprache?' },
  'wiz.regio.s': { nl: 'Je land bepaalt je tijdzone en munt. De taal is de taal waarin ik je klanten aanspreek — daar beslis jij over.', fr: "Votre pays détermine le fuseau horaire et la devise. La langue est celle dans laquelle je m'adresse à vos clients — c'est vous qui décidez.", en: "Your country sets your timezone and currency. The language is the one I speak to your customers in — that's your call.", de: 'Ihr Land bestimmt Zeitzone und Währung. Die Sprache ist die, in der ich Ihre Kunden anspreche — das entscheiden Sie.' },
  'wiz.regio.land': { nl: 'In welk land is je bedrijf gevestigd?', fr: 'Dans quel pays votre entreprise est-elle établie ?', en: 'Which country is your business based in?', de: 'In welchem Land ist Ihr Unternehmen ansässig?' },
  'wiz.regio.taal': { nl: 'In welke taal spreek ik je klanten aan?', fr: "Dans quelle langue dois-je m'adresser à vos clients ?", en: 'Which language should I speak to your customers in?', de: 'In welcher Sprache soll ich Ihre Kunden ansprechen?' },
  'wiz.bedrijf.t': { nl: 'Vertel me over je bedrijf', fr: 'Parlez-moi de votre entreprise', en: 'Tell me about your business', de: 'Erzählen Sie mir von Ihrem Unternehmen' },
  'wiz.bedrijf.s': { nl: 'Dit gebruik ik om je leads te beantwoorden. Hoe concreter je bent, hoe beter ik ze kan kwalificeren.', fr: "Je m'en sers pour répondre à vos prospects. Plus vous êtes précis, mieux je peux les qualifier.", en: 'I use this to answer your leads. The more specific you are, the better I can qualify them.', de: 'Damit beantworte ich Ihre Leads. Je konkreter Sie sind, desto besser kann ich sie qualifizieren.' },
  'wiz.bedrijf.v': { nl: 'Wat doet je kantoor?', fr: 'Que fait votre bureau ?', en: 'What does your office do?', de: 'Was macht Ihr Büro?' },
  'wiz.bedrijf.web': { nl: 'Website (optioneel)', fr: 'Site web (facultatif)', en: 'Website (optional)', de: 'Website (optional)' },
  'wiz.ai.t': { nl: 'Onder welke naam stel ik me voor?', fr: 'Sous quel nom dois-je me présenter ?', en: 'What name should I introduce myself under?', de: 'Unter welchem Namen stelle ich mich vor?' },
  'wiz.ai.s': { nl: 'Dit is het eerste dat je leads van me zien, nog voor jij iets hoeft te doen.', fr: "C'est la première chose que vos prospects voient de moi, avant même que vous n'interveniez.", en: 'This is the first thing your leads see from me, before you have to do anything.', de: 'Das ist das Erste, was Ihre Leads von mir sehen, noch bevor Sie etwas tun müssen.' },
  'wiz.kopp.t': { nl: 'Koppel WhatsApp en je agenda', fr: 'Connectez WhatsApp et votre agenda', en: 'Connect WhatsApp and your calendar', de: 'WhatsApp und Kalender verbinden' },
  'wiz.kopp.s': { nl: 'Hiermee praat ik met je leads en plan ik zelf afspraken in. Je kan dit ook later doen.', fr: "C'est ainsi que je parle à vos prospects et que je planifie moi-même les rendez-vous. Vous pouvez aussi le faire plus tard.", en: 'This is how I talk to your leads and book appointments myself. You can also do this later.', de: 'So spreche ich mit Ihren Leads und plane selbst Termine. Sie können das auch später tun.' },
  'wiz.klaar.t': { nl: 'Je bent klaar. Ik neem het over.', fr: 'Vous êtes prêt. Je prends le relais.', en: "You're set. I'll take it from here.", de: 'Sie sind bereit. Ich übernehme.' },
  'wiz.klaar.s': { nl: 'Deel deze link. Iedereen die hem invult, sta ik meteen te woord.', fr: 'Partagez ce lien. Toute personne qui le remplit, je lui réponds immédiatement.', en: 'Share this link. Anyone who fills it in, I answer straight away.', de: 'Teilen Sie diesen Link. Jeden, der ihn ausfüllt, beantworte ich sofort.' },
